// Which status changes the customer hears about, in their own language.
// Return an empty message to stay silent for a status.
const { phone, phone_number_id, order_number, order_type, language, status } = $input.first().json.body;
const n = '#' + order_number;

const templates = {
  accepted: {
    en: `✅ Order ${n} is confirmed! The kitchen has started on it.`,
    roman_ur: `✅ Aap ka order ${n} confirm ho gaya hai. Kitchen ne tayyari shuru kar di hai.`,
    ur: `✅ آپ کا آرڈر ${n} کنفرم ہو گیا ہے۔ کچن نے تیاری شروع کر دی ہے۔`,
  },
  // Delivery customers get the "on its way" message instead.
  ready: order_type === 'pickup' ? {
    en: `🛍️ Order ${n} is ready for pickup.`,
    roman_ur: `🛍️ Aap ka order ${n} tayyar hai. Aap aa kar le sakte hain.`,
    ur: `🛍️ آپ کا آرڈر ${n} تیار ہے۔ آپ آ کر لے سکتے ہیں۔`,
  } : null,
  out_for_delivery: {
    en: `🛵 Order ${n} is on its way!`,
    roman_ur: `🛵 Aap ka order ${n} rawana ho gaya hai!`,
    ur: `🛵 آپ کا آرڈر ${n} روانہ ہو گیا ہے!`,
  },
  cancelled: {
    en: `❌ Sorry, order ${n} has been cancelled by the restaurant. Message us here if you have any questions.`,
    roman_ur: `❌ Maazrat, aap ka order ${n} restaurant ki taraf se cancel kar diya gaya hai. Koi sawal ho to yahan message karein.`,
    ur: `❌ معذرت، آپ کا آرڈر ${n} ریسٹورنٹ کی طرف سے منسوخ کر دیا گیا ہے۔ کوئی سوال ہو تو یہاں میسج کریں۔`,
  },
};

const template = templates[status];
const message = template ? (template[language] ?? template.en) : '';
return [{ json: { phone, phone_number_id, order_number, status, message } }];
